<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';import './p6.css';
const token=new URLSearchParams(location.search).get('intake')??'',meta=ref<any>(null),error=ref(''),busy=ref(false),receipt=ref(''),requestId=ref(crypto.randomUUID());const form=reactive({name:'',companyName:'',phone:'',email:'',message:'',consent:false,website:''});
async function api(method='GET'){const response=await fetch('/api/v1/public-intake/'+encodeURIComponent(token),{method,headers:{'Content-Type':'application/json','Idempotency-Key':requestId.value},...(method==='POST'?{body:JSON.stringify(form)}:{})});const body=await response.json();if(!response.ok)throw new Error(response.status===404||response.status===403?'此表单已过期、已撤销或暂不可用，请联系提供链接的工作人员。':body.message??'提交未完成，请稍后重试');return body;}
async function submit(){if(busy.value)return;if(!form.phone&&!form.email){error.value='电话或邮箱至少填写一项，便于工作人员联系。';return;}busy.value=true;error.value='';try{const r=await api('POST');receipt.value=r.receiptId;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(async()=>{busy.value=true;try{meta.value=await api();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}});
</script>
<template><main class="intake-page p6"><section class="intake-card"><span class="intake-brand">彬彬 CRM · 客户联系</span><h1>{{meta?.name??'业务资料收集'}}</h1><p v-if="error" class="p6-error" role="alert">{{error}}</p><p v-if="busy&&!meta" class="p6-muted">正在加载表单…</p><div v-if="receipt" role="status"><h2>已收到你的资料</h2><p class="p6-muted">工作人员会根据你提供的联系方式跟进本次需求。</p><small>回执编号：{{receipt.slice(0,8)}}</small></div><form v-else-if="meta" @submit.prevent="submit"><fieldset :disabled="busy"><label>联系人姓名<input v-model="form.name" required maxlength="100" autocomplete="name"/></label><label v-if="meta.entityType==='LEAD'">公司名称<input v-model="form.companyName" required maxlength="200" autocomplete="organization"/></label><div class="p6-grid"><label>联系电话<input v-model="form.phone" maxlength="40" autocomplete="tel"/></label><label>联系邮箱<input v-model="form.email" type="email" maxlength="254" autocomplete="email"/></label></div><small>电话和邮箱至少填写一项。</small><label>需求说明<textarea v-model="form.message" required maxlength="4000" rows="5"/></label><label class="intake-honeypot" aria-hidden="true">网站<input v-model="form.website" tabindex="-1" autocomplete="off"/></label><label class="intake-consent"><input v-model="form.consent" type="checkbox" required/>同意工作人员使用上述资料就本次需求与我联系。</label><button class="btn primary" :disabled="busy">{{busy?'正在提交…':'提交资料'}}</button></fieldset></form></section></main></template>
<style scoped>.intake-page{min-height:100dvh;background:radial-gradient(ellipse at top right,#173b4170,transparent 65%),#101722;display:flex;align-items:center;justify-content:center;padding:24px;color:#e6efff}.intake-card{width:min(650px,100%);background:#18283cdd;border:1px solid #7899bd55;border-radius:18px;padding:32px;box-shadow:0 25px 70px #0004}.intake-card h1{font-size:25px;margin:20px 0}.intake-brand{font-size:13px;color:#99dfd3}.intake-card fieldset{display:grid;gap:17px}.intake-card .intake-consent{display:flex;flex-direction:row;align-items:flex-start;line-height:1.7}.intake-consent input{width:18px;margin-top:3px;accent-color:#69d7c4}.intake-honeypot{position:absolute;left:-10000px;width:1px;height:1px;overflow:hidden}@media(max-width:600px){.intake-page{padding:14px}.intake-card{padding:22px}}
</style>
